"""Compile measured reports only; no inferred accuracy or extrapolated speedups."""
from pathlib import Path
from collections import Counter
import argparse,importlib.metadata,json,platform,sys,statistics
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT))
from materflow.config import load_config
from materflow.schema import read_json,read_jsonl,write_json

def main():
    p=argparse.ArgumentParser();p.add_argument('--config',required=True);args=p.parse_args();c=load_config(args.config);out=c['output_dir'];s=read_json(out/'run_summary.json')
    qa=read_json(out/'diagnostics/validation.json');hot=read_json(out/'diagnostics/hot_cache_check.json');filters=read_json(out/'filter_report.json');ground=read_json(out/'ground_metrics.json');tracking=read_json(out/'tracking_metrics.json');caption=read_json(out/'caption_metrics.json')
    baseline={name:read_json(out/'baseline'/(name+'_metrics.json')) for name in ('ground','consolidate')}
    cold={name:read_json(out/'cold_v41'/(name+'_benchmark.json')) for name in ('ground','consolidate')}
    provenance=read_json(out/'baseline/caption_cache_provenance.json');identities=read_json(out/'identities.json');observations=read_jsonl(out/'observations.jsonl');derived=read_json(out/'derived.json');times=read_json(out/'time_mapping.json')
    repaired=read_json(out/'diagnostics/before_preprocessing_cache_audit_run_summary.json')['stages']['ground']
    version={}
    for name in ('torch','transformers','bitsandbytes','av','openpyxl','Pillow','numpy'):
        version[name]=importlib.metadata.version(name)
    review=[
      {'source_time_s':75.0,'preview':'diagnostics/preview_0000.jpg','finding':'Qwen display transcription 77.67 7.1 has unresolved numeric interpretation; bottle/background objects remain; no manual text correction applied.'},
      {'source_time_s':87.5,'preview':'diagnostics/preview_0375.jpg','finding':'SAM2 pipette_4 propagated box spreads over the balance enclosure; weighing-cup category/extent needs review. This is a visible localization error, not validated tracking accuracy.'},
      {'source_time_s':99.966667,'preview':'diagnostics/preview_0749.jpg','finding':'Last clock unbracketed by OCR anchors remains unresolved; bottle fragment has another public ID. Stable ledger does not guarantee successful physical re-identification.'},
      {'source_range_s':[75,100],'finding':'6 transfer candidates lack complete carrier bindings; no M/S or L nodes generated. Physical lineage end-to-end positive case was tested with unit evidence, not established in this real excerpt.'}]
    track_lengths={}
    for variant,tracking_path in (("V4.0",out/'baseline/tracking.json'),("V4.1",out/'tracking.json')):
        lengths=[len(row['history']) for row in read_json(tracking_path)['tracks']]
        track_lengths[variant]={'count':len(lengths),'single_frame':lengths.count(1),'median':statistics.median(lengths) if lengths else None,'minimum':min(lengths) if lengths else None,'maximum':max(lengths) if lengths else None,'histogram':dict(Counter(lengths))}
    oldconfig=load_config(ROOT/'output/clear_video/run.yaml')
    compared_parameters={key:{'V4.0':oldconfig.get(key),'V4.1':c.get(key)} for key in ('sample_fps','caption_fps','caption_interval_s','detection_fps','box_threshold','text_threshold','class_thresholds','window_frames','window_stride','track_chunk_frames','appearance_threshold')}
    comparison={stage:{'V4.0':baseline[stage],'V4.1':cold[stage]} for stage in ('ground','consolidate')}
    report={'schema_version':'ChemFlow-v4.1','run_id':c['run_id'],'source_range_s':c.get('ranges_s'),'sample_fps':c['sample_fps'],'source_resolution':[1920,1080],'versions':version,'platform':platform.platform(),'models':{k:c[k] for k in ('model_name','model_revision','grounding_model','grounding_revision','sam2_model','sam2_revision','dinov2_model','dinov2_revision')},
      'stage_measurements':s['stages'],'first_ground_attempt':read_json(out/'diagnostics/pre_resume_ground_metrics.json'),'ground_cache_repair_attempt':repaired,'isolated_visual_comparison':comparison,'hot_cache':hot,'caption_metrics':caption,
      'observation_counts':{k:filters[k] for k in ('raw_count','normalized_count','business_count')},'aggregation_reduction_from_normalized':1-filters['business_count']/filters['normalized_count'],'raw_to_business_reduction':1-filters['business_count']/filters['raw_count'],'filter_counts':{'rejected_tracks':len(filters['rejected_tracks']),'filtered_records':len(filters['filtered_records']),'reasons':dict(Counter(row['reason'] for row in filters['filtered_records']))},
      'track_length_comparison':track_lengths,'compared_parameters':compared_parameters,'business_counts':qa['record_counts'],'tracking_metrics':tracking,'public_objects':[row for row in identities.values() if row.get('object_id')],'instrument_classes':dict(Counter(o['instrument_class'] for o in observations if o.get('instrument_class'))),'clock_anchors':{'total':len(times['anchors']),'parsed':sum(bool(a.get('datetime')) for a in times['anchors'])},
      'legacy_caption_cache_entries':len(provenance['entries']),'legacy_caption_timing_measured':False,'human_reference_used':False,'human_accuracy_verified':False,'full_video_run_started':False,'quality_review':review,'validation':qa,
      'comparison_limits':['GPU power/clocks changed during the measurements; samples are included; no end-to-end speedup or accuracy ratio is asserted.','Same 125 source images and pinned vision models; legacy uses 25 warm V4.0 captions and per-class forwards; V4.1 uses 11 freshly inferred adaptive captions and configured category thresholds.','Model checkpoint files were already cached on disk. Detection/features caches are cold for isolated visual measurements.','Caption cold run has four batch calls including one invalid-frame retry; old caption cost was not measured; P8/180 MHz was observed externally during its run, but this older stage record lacks GPU samples and token timing.','Image preprocessing/feature work is included in inference_s; model_load_and_setup_s includes Python imports and setup, and no separate compile time was measured.']}
    write_json(out/'benchmark_report.json',report)
    lines=['# MaterFlow V4.1 measured 25-second benchmark','','Source: clear_video.mp4, 75 <= t < 100 s; 125 images at 5 fps; 11 adaptive Qwen frames. No human reference business rows used. Full video was not run.','','## Production run','','| Stage | Seconds | Cache / work |','|---|---:|---|',f"| prepare | {s['stages']['prepare']['elapsed_s']:.2f} | extraction + CPU OCR |",f"| caption | {s['stages']['caption']['elapsed_s']:.2f} | 11 frames, 4 batches including one retry; load {caption['load_s']:.2f}s |",f"| ground first attempt | {report['first_ground_attempt']['elapsed_s']:.2f} | inference, 125 forwards |",f"| ground cache repair, before provenance audit | {repaired['elapsed_s']:.2f} | 3 forwards + 122 verified frame-cache hits; includes load |",f"| ground final production verification | {s['stages']['ground']['elapsed_s']:.2f} | {ground['forward_calls']} forwards + {ground['cache_hits']} cache hits; includes load |",f"| consolidate | {s['stages']['consolidate']['elapsed_s']:.2f} | 4 shared multiobject sessions |",f"| derive | {s['stages']['derive']['elapsed_s']:.2f} | Excel + 750 source frames rendered silently |",f"| hot cache, all five stages | {hot['elapsed_s']:.2f} | all cached; zero new model calls |",'',
      'The first ground attempt completed before a vision-code revision changed its dependency signature. Its metrics were archived; first resume recomputed three affected frames. A subsequent cache-provenance audit added actual processor/library/parent-wrapper dependencies and the final production visual stages were rerun with cold caches. These measurements are separate.','','## Same-image isolated visual measurements','','| Variant / stage | Setup/load s | Inference s | Total s | Calls |','|---|---:|---:|---:|---|']
    for stage in ('ground','consolidate'):
        old=baseline[stage];new=cold[stage];m=new['metrics']
        oldcalls=str(old['forward_calls'])+' per-class' if stage=='ground' else str(old['counts'])
        newcalls=str(m['forward_calls'])+' multi-class' if stage=='ground' else str({k:v for k,v in m.items() if 'forwards' in k or 'sessions' in k})
        lines.append(f"| V4.0 {stage} | {old['model_load_s']:.2f} | {old['inference_s']:.2f} | {old['total_s']:.2f} | {oldcalls} |")
        lines.append(f"| V4.1 {stage} | {new['model_load_and_setup_s']:.2f} | {new['inference_s']:.2f} | {new['total_s']:.2f} | {newcalls} |")
    lines+=['','## Conditions and limits','']+['- '+x for x in report['comparison_limits']]
    lines+=['','GPU snapshots for each visual stage are in benchmark_report.json; do not treat these measurements as a controlled speedup ratio.','','## Business and tracking results','',f"Raw {filters['raw_count']} -> filtered/normalized {filters['normalized_count']} -> aggregated {filters['business_count']}. Aggregation alone reduced normalized rows by {report['aggregation_reduction_from_normalized']:.1%}; filtering plus aggregation reduced raw rows by {report['raw_to_business_reduction']:.1%}.",f"Business counts: {qa['record_counts']}. Instrument-class rows: {report['instrument_classes']}. Tracks: {tracking['global_tracks']}; single-frame: {tracking['single_frame_tracks']}; median detection-history length: {tracking['median_history']}.",f"Rejected tracks: {len(filters['rejected_tracks'])}; filtered records: {len(filters['filtered_records'])}. O/E/M/S/L use the persistent ledger; public object aliases remain tied to their tracks.",f"Clock OCR anchors: {report['clock_anchors']}. Records use separate time_mapping.json; final unbracketed tail remains unresolved.",f"Old/new detection-history lengths: {track_lengths}.",'','## Reviewed examples','']
    for row in review:lines.append('- '+json.dumps(row,ensure_ascii=False))
    lines+=['','## Verification','', '63 regression tests passed. Three workbooks match automatic JSON cell by cell; public references and every stage artifact hash checked. Annotated video: 750 frames, 1920x1080, 30fps, identical relative frame PTS and zero audio streams. Preview first/middle/last frames were inspected. This verifies output integrity, not visual accuracy.','', 'Real materials/lineage remain empty for this excerpt because carrier evidence is incomplete. No successful real physical-lineage reconstruction or independent accuracy/recall evaluation is claimed.']
    (out/'benchmark_report.md').write_text('\n'.join(lines),encoding='utf-8')
    print(out/'benchmark_report.md')
if __name__=='__main__':main()
